        "answer_outline": "বাংলাদেশের প্রধান রপ্তানি পণ্য তৈরি পোশাক — রপ্তানি আয়ের প্রায় চার-পঞ্চমাংশের বেশি (প্রায় ৮০%+) এই খাত থেকে আসে (EPB/BGMEA তথ্য অনুযায়ী)। তাই তৈরি পোশাক রপ্তানি কমলে বৈদেশিক মুদ্রা আয় ও কর্মসংস্থান দুটোই ক্ষতিগ্রস্ত হয়; রপ্তানি পণ্যে বৈচিত্র্য না থাকায় এই নির্ভরতা ঝুঁকিও তৈরি করে।"
